'use strict';
const fs = require('fs');
const regions = ['north', 'south', 'east', 'west'];
const inspectorReported = {
  north: { count: 10, units: 90, weighted: 167 },
  south: { count: 10, units: 94, weighted: 171 },
  east: { count: 10, units: 98, weighted: 209 },
  west: { count: 10, units: 85, weighted: 145 },
};
const expectedKeys = ['id', 'units', 'weight'];
const computed = {};
let fail = 0;
for (const r of regions) {
  const raw = fs.readFileSync(r + '.json', 'utf8');
  const data = JSON.parse(raw);
  if (!Array.isArray(data)) { console.log(r + ': NOT AN ARRAY'); fail++; continue; }
  const ids = new Set();
  let count = 0, units = 0, weighted = 0;
  for (const rec of data) {
    count++;
    const keys = Object.keys(rec).sort();
    if (keys.join(',') !== expectedKeys.slice().sort().join(',')) { console.log(r + ': bad keys ' + keys); fail++; }
    for (const f of ['id', 'units', 'weight']) {
      if (!Number.isInteger(rec[f])) { console.log(r + ': non-integer ' + f + ' in ' + JSON.stringify(rec)); fail++; }
    }
    if (ids.has(rec.id)) { console.log(r + ': duplicate id ' + rec.id); fail++; }
    ids.add(rec.id);
    units += rec.units;
    weighted += rec.units * rec.weight;
  }
  const sortedIds = Array.from(ids).sort((a, b) => a - b);
  const contiguous = sortedIds.length === count && sortedIds.every((v, i) => v === i + 1);
  if (!contiguous) { console.log(r + ': ids not contiguous 1..n: ' + sortedIds.join(',')); fail++; }
  computed[r] = { count, units, weighted };
  const ins = inspectorReported[r];
  const match = ins.count === count && ins.units === units && ins.weighted === weighted;
  if (!match) fail++;
  console.log(r + ': records=' + count + ' contiguous=' + contiguous + ' units=' + units + ' weighted=' + weighted +
    ' | inspector ' + ins.count + '/' + ins.units + '/' + ins.weighted + ' -> ' + (match ? 'MATCH' : 'MISMATCH'));
}
const answer = JSON.parse(fs.readFileSync('answer.json', 'utf8'));
const topKeys = Object.keys(answer).sort().join(',');
if (topKeys !== 'grand_units,grand_weighted,regions') { console.log('answer.json bad top-level keys: ' + topKeys); fail++; }
const answerRegions = Object.keys(answer.regions || {}).sort().join(',');
if (answerRegions !== 'east,north,south,west') { console.log('answer.json bad region keys: ' + answerRegions); fail++; }
let gu = 0, gw = 0;
for (const r of regions) {
  const e = answer.regions[r];
  if (!e) { console.log(r + ': missing in answer.json'); fail++; continue; }
  const ek = Object.keys(e).sort().join(',');
  if (ek !== 'count,units,weighted') { console.log(r + ': answer entry keys ' + ek); fail++; }
  if (e.count !== computed[r].count || e.units !== computed[r].units || e.weighted !== computed[r].weighted) {
    console.log(r + ': answer.json MISMATCH ' + JSON.stringify(e) + ' vs ' + JSON.stringify(computed[r])); fail++;
  }
  gu += computed[r].units;
  gw += computed[r].weighted;
}
if (answer.grand_units !== gu || answer.grand_weighted !== gw) {
  console.log('grand MISMATCH answer ' + answer.grand_units + '/' + answer.grand_weighted + ' computed ' + gu + '/' + gw); fail++;
}
console.log('grand_units=' + gu + ' grand_weighted=' + gw);
console.log(fail === 0 ? 'VERIFIED' : 'FAILURES=' + fail);
process.exit(fail === 0 ? 0 : 1);

